package main

import (
	"bufio"
	"flag"
	"fmt"
	"os"
	"regexp"
	"strings"
)

type options struct {
	absolute, assertions, blank, excludeOnly bool
	ignoreGenerated, ignoreTests, verbose   bool
	exclude, ignorePackages, mod            string
	ignores                                ignorePatterns
	tags                                   tagList
	exclusions                             map[string]bool
}

type ignorePatterns map[string]*regexp.Regexp

func (p *ignorePatterns) String() string { return "" }
func (p *ignorePatterns) Set(value string) error {
	if *p == nil {
		*p = make(ignorePatterns)
	}
	for _, part := range strings.Split(value, ",") {
		if part == "" {
			continue
		}
		pkg, pattern := "", part
		if i := strings.IndexByte(part, ':'); i >= 0 {
			pkg, pattern = part[:i], part[i+1:]
		}
		r, err := regexp.Compile(pattern)
		if err != nil {
			return err
		}
		(*p)[pkg] = r
	}
	return nil
}

type tagList []string

func (t *tagList) String() string { return "" }
func (t *tagList) Set(s string) error {
	*t = append(*t, strings.Fields(strings.ReplaceAll(s, ",", " "))...)
	return nil
}

func parseOptions() (*options, []string, error) {
	o := &options{ignores: make(ignorePatterns), exclusions: make(map[string]bool)}
	f := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)
	f.BoolVar(&o.absolute, "abspath", false, "print absolute paths to files")
	f.BoolVar(&o.assertions, "asserts", false, "if true, check for ignored type assertion results")
	f.BoolVar(&o.blank, "blank", false, "if true, check for errors assigned to blank identifier")
	f.StringVar(&o.exclude, "exclude", "", "Path to a file containing a list of functions to exclude from checking")
	f.BoolVar(&o.excludeOnly, "excludeonly", false, "Use only excludes from -exclude file")
	f.Var(&o.ignores, "ignore", "[deprecated] comma-separated list of pairs of the form pkg:regex\n            the regex is used to ignore names within pkg.")
	f.BoolVar(&o.ignoreGenerated, "ignoregenerated", false, "if true, checking of files with generated code is disabled")
	f.StringVar(&o.ignorePackages, "ignorepkg", "", "comma-separated list of package paths to ignore")
	f.BoolVar(&o.ignoreTests, "ignoretests", false, "if true, checking of _test.go files is disabled")
	f.StringVar(&o.mod, "mod", "", "module download mode to use: readonly or vendor. See 'go help modules' for more.")
	f.Var(&o.tags, "tags", "comma or space-separated list of build tags to include")
	f.BoolVar(&o.verbose, "verbose", false, "produce more verbose logging")
	if err := f.Parse(os.Args[1:]); err != nil {
		return nil, nil, err
	}
	return o, f.Args(), nil
}

func (o *options) prepare() error {
	if !o.excludeOnly {
		for _, recv := range []string{"*bytes.Buffer", "*strings.Builder"} {
			for _, method := range []string{"Write", "WriteByte", "WriteRune", "WriteString"} {
				o.exclusions["("+recv+")."+method] = true
			}
		}
		for _, method := range []string{"Write", "WriteByte", "WriteString"} {
			o.exclusions["(*hash/maphash.Hash)."+method] = true
		}
		for _, recv := range []string{"hash.Hash", "hash.Hash32", "hash.Hash64"} {
			o.exclusions["("+recv+").Write"] = true
		}
		for _, fn := range []string{
			"fmt.Print", "fmt.Printf", "fmt.Println", "math/rand.Read", "(*math/rand.Rand).Read",
			"(*io.PipeReader).CloseWithError", "(*io.PipeWriter).CloseWithError",
		} {
			o.exclusions[fn] = true
		}
		for _, fn := range []string{"fmt.Fprint", "fmt.Fprintf", "fmt.Fprintln"} {
			for _, arg := range []string{"*bytes.Buffer", "*strings.Builder", "os.Stderr"} {
				o.exclusions[fn+"("+arg+")"] = true
			}
		}
	}
	if o.exclude != "" {
		f, err := os.Open(o.exclude)
		if err != nil {
			return err
		}
		defer f.Close()
		s := bufio.NewScanner(f)
		for s.Scan() {
			line := s.Text()
			if line != "" && !strings.HasPrefix(line, "//") {
				o.exclusions[line] = true
			}
		}
		if err := s.Err(); err != nil {
			return err
		}
	}
	for _, pkg := range strings.Split(o.ignorePackages, ",") {
		if pkg != "" {
			o.ignores[pkg] = regexp.MustCompile(".*")
		}
	}
	return nil
}

func run() int {
	o, args, err := parseOptions()
	if err != nil {
		return 2
	}
	if err = o.prepare(); err != nil {
		fmt.Fprintf(os.Stderr, "Could not read exclude file: %v\n", err)
		return 2
	}
	if len(args) == 0 {
		args = []string{"."}
	}
	l, err := loadPackages(o, args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: failed to check packages: %v\n", err)
		return 2
	}
	if l == nil {
		return 0
	}
	for _, p := range l.roots {
		l.source(p)
	}
	for _, p := range l.roots {
		if len(p.errors) != 0 {
			fmt.Fprintf(os.Stderr, "error: failed to check packages: errors while loading package %s: [%s]\n", p.meta.ImportPath, strings.Join(p.errors, " "))
			return 2
		}
	}
	c := newChecker(o, l)
	for _, p := range l.roots {
		if p.pkg == nil {
			continue
		}
		if o.verbose {
			fmt.Fprintf(os.Stderr, "checking %s\n", packagePath(p.meta.ImportPath))
		}
		c.check(p)
	}
	if c.output() {
		return 1
	}
	return 0
}

func main() { os.Exit(run()) }
