cat > src/checker.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type finding struct {
	pos  token.Position
	name string
}

type checker struct {
	o        *options
	loader   *loader
	pkg      *sourcePackage
	findings map[string]finding
	errType  *types.Interface
}

func newChecker(o *options, l *loader) *checker {
	return &checker{
		o: o, loader: l, findings: make(map[string]finding),
		errType: types.Universe.Lookup("error").Type().Underlying().(*types.Interface),
	}
}

var generatedComment = regexp.MustCompile(`^// Code generated .* DO NOT EDIT\.$`)

func (c *checker) check(p *sourcePackage) {
	c.pkg = p
	for _, f := range p.files {
		if c.o.ignoreTests && strings.HasSuffix(c.loader.fset.Position(f.Pos()).Filename, "_test.go") {
			continue
		}
		generated := false
		if c.o.ignoreGenerated {
			for _, group := range f.Comments {
				for _, comment := range group.List {
					if generatedComment.MatchString(comment.Text) {
						generated = true
					}
				}
			}
		}
		if !generated {
			ast.Walk(c, f)
		}
	}
}

func (c *checker) add(pos token.Pos, call *ast.CallExpr) {
	p := c.loader.fset.Position(pos)
	key := fmt.Sprintf("%s:%d:%d", p.Filename, p.Line, p.Column)
	c.findings[key] = finding{p, c.callName(call)}
}

func (c *checker) Visit(node ast.Node) ast.Visitor {
	switch n := node.(type) {
	case *ast.ExprStmt:
		if call, ok := n.X.(*ast.CallExpr); ok {
			c.discardedCall(call)
		}
	case *ast.GoStmt:
		c.discardedCall(n.Call)
	case *ast.DeferStmt:
		c.discardedCall(n.Call)
	case *ast.AssignStmt:
		if c.assignment(n.Lhs, n.Rhs) {
			return nil
		}
	case *ast.ValueSpec:
		lhs := make([]ast.Expr, len(n.Names))
		for i, id := range n.Names {
			lhs[i] = id
		}
		if c.assignment(lhs, n.Values) {
			return nil
		}
	case *ast.TypeAssertExpr:
		if c.o.assertions && n.Type != nil {
			c.add(n.Pos(), nil)
		}
	}
	return c
}

func isBlank(e ast.Expr) bool {
	id, ok := e.(*ast.Ident)
	return ok && id.Name == "_"
}

func (c *checker) assignment(lhs, rhs []ast.Expr) bool {
	if len(rhs) == 1 {
		switch e := rhs[0].(type) {
		case *ast.CallExpr:
			if c.o.blank && !c.ignored(e) {
				flags := c.errorResults(e)
				for i, l := range lhs {
					if i < len(flags) && flags[i] && isBlank(l) {
						c.add(l.Pos(), e)
					}
				}
			}
		case *ast.TypeAssertExpr:
			if len(lhs) == 2 {
				if c.o.assertions && c.o.blank && isBlank(lhs[1]) {
					c.add(lhs[1].Pos(), nil)
				}
				return true
			}
		}
	} else {
		for i, e := range rhs {
			if i >= len(lhs) {
				break
			}
			switch e := e.(type) {
			case *ast.CallExpr:
				if c.o.blank && isBlank(lhs[i]) && !c.ignored(e) {
					flags := c.errorResults(e)
					if len(flags) > 0 && flags[0] {
						c.add(lhs[i].Pos(), e)
					}
				}
			case *ast.TypeAssertExpr:
				if c.o.assertions {
					c.add(lhs[i].Pos(), nil)
				}
			}
		}
	}
	return false
}

func (c *checker) discardedCall(call *ast.CallExpr) {
	if c.ignored(call) {
		return
	}
	for _, b := range c.errorResults(call) {
		if b {
			c.add(call.Lparen, call)
			return
		}
	}
}

func (c *checker) isError(t types.Type) bool {
	switch t.(type) {
	case *types.Named, *types.Pointer:
		return types.Implements(t, c.errType)
	}
	return false
}

func (c *checker) errorResults(call *ast.CallExpr) []bool {
	t := c.pkg.info.TypeOf(call)
	if t == nil {
		return nil
	}
	var flags []bool
	if tuple, ok := t.(*types.Tuple); ok {
		flags = make([]bool, tuple.Len())
		for i := range flags {
			flags[i] = c.isError(tuple.At(i).Type())
		}
	} else {
		flags = []bool{c.isError(t)}
	}
	if c.loader.aliasMode {
		sig := signature(c.pkg.info.TypeOf(call.Fun))
		aliases, ok := c.loader.aliases[sig]
		if !ok {
			fun := call.Fun
			for {
				switch f := fun.(type) {
				case *ast.IndexExpr:
					fun = f.X
				case *ast.IndexListExpr:
					fun = f.X
				case *ast.ParenExpr:
					fun = f.X
				default:
					goto resolved
				}
			}
		resolved:
			var obj types.Object
			switch f := fun.(type) {
			case *ast.Ident:
				obj = c.pkg.info.ObjectOf(f)
			case *ast.SelectorExpr:
				obj = c.pkg.info.ObjectOf(f.Sel)
			}
			if obj != nil {
				aliases = c.loader.aliases[signature(obj.Type())]
			}
		}
		for i, a := range aliases {
			if a && i < len(flags) {
				flags[i] = false
			}
		}
	}
	return flags
}

func (c *checker) callName(call *ast.CallExpr) string {
	if call == nil {
		return ""
	}
	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if fn, ok := c.pkg.info.ObjectOf(sel.Sel).(*types.Func); ok {
			return fn.FullName()
		}
	}
	return ""
}

func (c *checker) ignored(call *ast.CallExpr) bool {
	if call == nil {
		return false
	}
	var id *ast.Ident
	switch f := call.Fun.(type) {
	case *ast.Ident:
		id = f
	case *ast.SelectorExpr:
		id = f.Sel
	}
	if id != nil {
		if r := c.o.ignores[""]; r != nil && r.MatchString(id.Name) {
			return true
		}
		if obj := c.pkg.info.ObjectOf(id); obj != nil && obj.Pkg() != nil {
			if r := c.o.ignores[obj.Pkg().Path()]; r != nil && r.MatchString(id.Name) {
				return true
			}
		}
	}
	name := c.callName(call)
	if name == "" {
		return false
	}
	if c.o.exclusions[name] {
		return true
	}
	if len(call.Args) > 0 {
		typeName := ""
		if t := c.pkg.info.TypeOf(call.Args[0]); t != nil {
			typeName = t.String()
		}
		if sel, ok := call.Args[0].(*ast.SelectorExpr); ok {
			if obj := c.pkg.info.ObjectOf(sel.Sel); obj != nil && obj.Pkg() != nil && obj.Pkg().Path() == "os" && (obj.Name() == "Stdout" || obj.Name() == "Stderr") {
				typeName = "os." + obj.Name()
			}
		}
		if c.o.exclusions[name+"("+typeName+")"] {
			return true
		}
	}
	if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
		if selection := c.pkg.info.Selections[sel]; selection != nil {
			seen := make(map[types.Type]bool)
			var search func(types.Type) bool
			search = func(t types.Type) bool {
				if t == nil || seen[t] {
					return false
				}
				seen[t] = true
				iface, ok := t.Underlying().(*types.Interface)
				if !ok {
					return false
				}
				if c.o.exclusions["("+t.String()+")."+sel.Sel.Name] {
					return true
				}
				for j := 0; j < iface.NumEmbeddeds(); j++ {
					if search(iface.EmbeddedType(j)) {
						return true
					}
				}
				return false
			}
			if search(selection.Recv()) {
				return true
			}
		}
	}
	return false
}

func (c *checker) output() bool {
	list := make([]finding, 0, len(c.findings))
	for _, f := range c.findings {
		list = append(list, f)
	}
	sort.Slice(list, func(i, j int) bool {
		a, b := list[i].pos, list[j].pos
		if a.Filename != b.Filename {
			return a.Filename < b.Filename
		}
		if a.Line != b.Line {
			return a.Line < b.Line
		}
		return a.Column < b.Column
	})
	cwd, _ := os.Getwd()
	lines := make(map[string][]string)
	for _, f := range list {
		pos := f.pos
		if _, ok := lines[pos.Filename]; !ok {
			content, err := os.ReadFile(pos.Filename)
			if err == nil {
				lines[pos.Filename] = strings.Split(string(content), "\n")
			} else {
				lines[pos.Filename] = nil
			}
		}
		text := "??"
		if ls := lines[pos.Filename]; pos.Line > 0 && pos.Line <= len(ls) {
			text = strings.TrimSpace(ls[pos.Line-1])
		}
		if !c.o.absolute {
			if rel, err := filepath.Rel(cwd, pos.Filename); err == nil {
				pos.Filename = rel
			}
		}
		if c.o.verbose && f.name != "" {
			fmt.Printf("%s:\t%s\t%s\n", pos.String(), f.name, text)
		} else {
			fmt.Printf("%s:\t%s\n", pos.String(), text)
		}
	}
	return len(list) != 0
}
