cat > src/loader.go <<'EOF'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/ast"
	"go/importer"
	"go/parser"
	"go/scanner"
	"go/token"
	"go/types"
	"io"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
)

type listError struct {
	Pos string
	Err string
}

type moduleInfo struct {
	GoVersion string
}

type packageMeta struct {
	Dir, ImportPath, Name, Export string
	GoFiles, CompiledGoFiles      []string
	Imports                      []string
	ImportMap                    map[string]string
	DepOnly, Standard             bool
	ForTest                      string
	Module                       *moduleInfo
	Error                        *listError
}

type sourcePackage struct {
	meta   *packageMeta
	files  []*ast.File
	info   *types.Info
	pkg    *types.Package
	errors []string
	state  int
}

type loader struct {
	fset       *token.FileSet
	packages   map[string]*sourcePackage
	roots      []*sourcePackage
	exports    types.Importer
	aliases    map[*types.Signature][]bool
	aliasMode  bool
}

func packagePath(id string) string {
	if i := strings.Index(id, " ["); i >= 0 {
		return id[:i]
	}
	return id
}

func loadPackages(o *options, args []string) (*loader, error) {
	goPath, err := exec.LookPath("go")
	if err != nil {
		return nil, fmt.Errorf("err: go command required, not found: %v: stderr: ", err)
	}
	patterns := make([]string, 0, len(args))
	for _, arg := range args {
		if strings.HasPrefix(arg, "file=") {
			file, e := filepath.Abs(strings.TrimPrefix(arg, "file="))
			if e != nil {
				return nil, e
			}
			patterns = append(patterns, filepath.Dir(file))
		} else {
			patterns = append(patterns, arg)
		}
	}
	cmdArgs := []string{"list", "-e", "-json", "-compiled", "-export", "-deps"}
	if !o.ignoreTests {
		cmdArgs = append(cmdArgs, "-test")
	}
	if len(o.tags) > 0 {
		cmdArgs = append(cmdArgs, "-tags="+strings.Join(o.tags, ","))
	}
	if o.mod != "" {
		cmdArgs = append(cmdArgs, "-mod="+o.mod)
	}
	cmdArgs = append(cmdArgs, "--")
	cmdArgs = append(cmdArgs, patterns...)
	cmd := exec.Command(goPath, cmdArgs...)
	var out, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &out, &stderr
	err = cmd.Run()
	l := &loader{
		fset: token.NewFileSet(), packages: make(map[string]*sourcePackage),
		aliases: make(map[*types.Signature][]bool), aliasMode: true,
	}
	for _, s := range strings.Split(os.Getenv("GODEBUG"), ",") {
		if strings.HasPrefix(s, "gotypesalias=") {
			l.aliasMode = strings.TrimPrefix(s, "gotypesalias=") != "0"
		}
	}
	if err != nil && out.Len() == 0 {
		s := stderr.String()
		if strings.HasPrefix(s, "go: cannot find main module") || strings.HasPrefix(s, "go: go.mod file not found") {
			return nil, nil
		}
		if strings.HasPrefix(s, "named files must") {
			return nil, fmt.Errorf("-: %s", strings.TrimSpace(s))
		}
		if strings.HasPrefix(s, "stat ") && strings.Contains(s, ".go:") {
			m := &packageMeta{ImportPath: "command-line-arguments", Error: &listError{Err: strings.TrimSpace(s)}}
			p := &sourcePackage{meta: m}
			l.roots = []*sourcePackage{p}
			l.packages[m.ImportPath] = p
			return l, nil
		}
		return nil, fmt.Errorf("err: %v: stderr: %s", err, s)
	}
	decoder := json.NewDecoder(&out)
	for {
		m := new(packageMeta)
		if e := decoder.Decode(m); e != nil {
			if e == io.EOF {
				break
			}
			return nil, e
		}
		p := &sourcePackage{meta: m}
		l.packages[m.ImportPath] = p
		if !m.DepOnly {
			l.roots = append(l.roots, p)
		}
	}
	l.exports = importer.ForCompiler(l.fset, "gc", func(path string) (io.ReadCloser, error) {
		if p := l.packages[path]; p != nil && p.meta.Export != "" {
			return os.Open(p.meta.Export)
		}
		return nil, fmt.Errorf("no export data for %s", path)
	})
	return l, nil
}

func (l *loader) source(p *sourcePackage) *types.Package {
	if p.state != 0 {
		return p.pkg
	}
	p.state = 1
	m := p.meta
	if m.Error != nil {
		pos := m.Error.Pos
		if pos == "" {
			pos = "-"
		}
		p.errors = append(p.errors, pos+": "+strings.TrimSpace(m.Error.Err))
	}
	files := m.CompiledGoFiles
	if len(files) == 0 {
		files = m.GoFiles
	}
	for _, name := range files {
		if !filepath.IsAbs(name) {
			name = filepath.Join(m.Dir, name)
		}
		name, _ = filepath.Abs(name)
		f, err := parser.ParseFile(l.fset, name, nil, parser.ParseComments|parser.AllErrors)
		if err != nil {
			if es, ok := err.(scanner.ErrorList); ok {
				for _, e := range es {
					p.errors = append(p.errors, e.Error())
				}
			} else {
				p.errors = append(p.errors, err.Error())
			}
		}
		if f != nil {
			p.files = append(p.files, f)
		}
	}
	if len(p.files) == 0 {
		p.state = 2
		return nil
	}
	p.info = &types.Info{
		Types: make(map[ast.Expr]types.TypeAndValue),
		Defs: make(map[*ast.Ident]types.Object), Uses: make(map[*ast.Ident]types.Object),
		Selections: make(map[*ast.SelectorExpr]*types.Selection),
		Instances: make(map[*ast.Ident]types.Instance),
		Implicits: make(map[ast.Node]types.Object), Scopes: make(map[ast.Node]*types.Scope),
	}
	arch := os.Getenv("GOARCH")
	if arch == "" {
		arch = runtime.GOARCH
	}
	config := types.Config{
		Importer: packageImporter{l, p},
		Sizes: types.SizesFor("gc", arch),
		FakeImportC: true,
		Error: func(err error) { p.errors = append(p.errors, err.Error()) },
	}
	if m.Module != nil && m.Module.GoVersion != "" {
		config.GoVersion = "go" + m.Module.GoVersion
	}
	p.pkg, _ = config.Check(packagePath(m.ImportPath), l.fset, p.files, p.info)
	l.recordAliases(p)
	p.state = 2
	return p.pkg
}

type packageImporter struct {
	loader *loader
	from   *sourcePackage
}

func (i packageImporter) Import(path string) (*types.Package, error) {
	return i.ImportFrom(path, "", 0)
}
func (i packageImporter) ImportFrom(path, dir string, mode types.ImportMode) (*types.Package, error) {
	if path == "unsafe" {
		return types.Unsafe, nil
	}
	if v := i.from.meta.ImportMap[path]; v != "" {
		path = v
	}
	p := i.loader.packages[path]
	if p == nil || p.meta.Name == "" {
		return nil, fmt.Errorf("invalid package name: %q", "")
	}
	if p.meta.Standard && p.meta.Export != "" && i.loader.exports != nil {
		if pkg, err := i.loader.exports.Import(path); err == nil {
			return pkg, nil
		}
	}
	if p.state == 1 {
		return nil, fmt.Errorf("import cycle not allowed")
	}
	if pkg := i.loader.source(p); pkg != nil {
		return pkg, nil
	}
	return nil, fmt.Errorf("invalid package name: %q", p.meta.Name)
}

func signature(t types.Type) *types.Signature {
	if t == nil {
		return nil
	}
	s, _ := t.Underlying().(*types.Signature)
	return s
}

// The runtime used by the reference represents declared aliases separately.
// Retain that bit of spelling information in addition to the standard type data.
func (l *loader) recordAliases(p *sourcePackage) {
	if !l.aliasMode || p.info == nil {
		return
	}
	record := func(sig *types.Signature, ft *ast.FuncType) {
		if sig == nil || ft == nil || ft.Results == nil {
			return
		}
		flags := []bool{}
		for _, field := range ft.Results.List {
			alias := false
			var name *ast.Ident
			switch t := field.Type.(type) {
			case *ast.Ident:
				name = t
			case *ast.SelectorExpr:
				name = t.Sel
			}
			if name != nil {
				if obj, ok := p.info.ObjectOf(name).(*types.TypeName); ok {
					alias = obj.IsAlias()
				}
			}
			n := len(field.Names)
			if n == 0 {
				n = 1
			}
			for k := 0; k < n; k++ {
				flags = append(flags, alias)
			}
		}
		l.aliases[sig] = flags
	}
	for _, file := range p.files {
		ast.Inspect(file, func(n ast.Node) bool {
			switch n := n.(type) {
			case *ast.FuncDecl:
				if obj := p.info.ObjectOf(n.Name); obj != nil {
					record(signature(obj.Type()), n.Type)
				}
			case *ast.FuncType:
				record(signature(p.info.TypeOf(n)), n)
			case *ast.FuncLit:
				record(signature(p.info.TypeOf(n)), n.Type)
			}
			return true
		})
	}
}
