package main

import (
	"go/ast"
	"go/token"
	"go/types"
	"strings"
)

type typeSpelling struct {
	pkg  *sourcePackage
	expr ast.Expr
}

func qualifiedName(obj types.Object) string {
	if obj.Pkg() == nil {
		return obj.Name()
	}
	return obj.Pkg().Path() + "." + obj.Name()
}

func typeSyntaxString(p *sourcePackage, expr ast.Expr) string {
	expr = unparen(expr)
	if obj, ok := expressionObject(p.info, expr).(*types.TypeName); ok {
		return qualifiedName(obj)
	}
	switch e := expr.(type) {
	case *ast.StarExpr:
		return "*" + typeSyntaxString(p, e.X)
	case *ast.ArrayType:
		size := ""
		if e.Len != nil {
			if v := p.info.Types[e.Len].Value; v != nil {
				size = v.ExactString()
			} else {
				break
			}
		}
		return "[" + size + "]" + typeSyntaxString(p, e.Elt)
	case *ast.MapType:
		return "map[" + typeSyntaxString(p, e.Key) + "]" + typeSyntaxString(p, e.Value)
	case *ast.ChanType:
		prefix := "chan "
		if e.Dir == ast.SEND {
			prefix = "chan<- "
		} else if e.Dir == ast.RECV {
			prefix = "<-chan "
		}
		return prefix + typeSyntaxString(p, e.Value)
	case *ast.IndexExpr:
		return typeSyntaxString(p, e.X) + "[" + typeSyntaxString(p, e.Index) + "]"
	case *ast.IndexListExpr:
		args := []string{}
		for _, a := range e.Indices {
			args = append(args, typeSyntaxString(p, a))
		}
		return typeSyntaxString(p, e.X) + "[" + strings.Join(args, ", ") + "]"
	}
	if t := p.info.TypeOf(expr); t != nil {
		return t.String()
	}
	return ""
}

func hasTypeParameter(t types.Type) bool {
	switch t := t.(type) {
	case *types.TypeParam:
		return true
	case *types.Pointer:
		return hasTypeParameter(t.Elem())
	case *types.Slice:
		return hasTypeParameter(t.Elem())
	case *types.Array:
		return hasTypeParameter(t.Elem())
	case *types.Map:
		return hasTypeParameter(t.Key()) || hasTypeParameter(t.Elem())
	case *types.Chan:
		return hasTypeParameter(t.Elem())
	case *types.Named:
		for i := 0; i < t.TypeArgs().Len(); i++ {
			if hasTypeParameter(t.TypeArgs().At(i)) {
				return true
			}
		}
	}
	return false
}

func (l *loader) expressionTypeString(p *sourcePackage, expr ast.Expr, seen map[types.Object]bool) string {
	t := p.info.TypeOf(expr)
	fallback := ""
	if t != nil {
		fallback = t.String()
	}
	if !l.aliasMode {
		return fallback
	}
	expr = unparen(expr)
	if p.info.Types[expr].IsType() {
		return typeSyntaxString(p, expr)
	}
	if obj := expressionObject(p.info, expr); obj != nil && !seen[obj] {
		if v, ok := l.aliasValues[obj]; ok {
			if v.typ != nil {
				return typeSyntaxString(v.pkg, v.typ)
			}
			if v.expr != nil {
				seen[obj] = true
				defer delete(seen, obj)
				if call, ok := unparen(v.expr).(*ast.CallExpr); ok {
					if s := l.resultTypeString(v.pkg, call, v.index); s != "" {
						return s
					}
				}
				return l.expressionTypeString(v.pkg, v.expr, seen)
			}
		}
	}
	switch e := expr.(type) {
	case *ast.UnaryExpr:
		if e.Op == token.AND {
			return "*" + l.expressionTypeString(p, e.X, seen)
		}
	case *ast.StarExpr:
		v := l.expressionTypeString(p, e.X, seen)
		if strings.HasPrefix(v, "*") {
			return v[1:]
		}
	case *ast.CompositeLit:
		if e.Type != nil {
			return typeSyntaxString(p, e.Type)
		}
	case *ast.CallExpr:
		if p.info.Types[e.Fun].IsType() {
			return typeSyntaxString(p, e.Fun)
		}
		if id, ok := e.Fun.(*ast.Ident); ok && len(e.Args) > 0 {
			if _, builtin := p.info.ObjectOf(id).(*types.Builtin); builtin {
				if id.Name == "new" {
					return "*" + typeSyntaxString(p, e.Args[0])
				}
				if id.Name == "make" {
					return typeSyntaxString(p, e.Args[0])
				}
			}
		}
		if _, tuple := t.(*types.Tuple); !tuple {
			if s := l.resultTypeString(p, e, 0); s != "" {
				return s
			}
		}
	}
	return fallback
}

func (l *loader) resultTypeString(p *sourcePackage, call *ast.CallExpr, index int) string {
	sig := signature(p.info.TypeOf(call.Fun))
	fun := unparen(call.Fun)
	switch f := fun.(type) {
	case *ast.IndexExpr:
		fun = unparen(f.X)
	case *ast.IndexListExpr:
		fun = unparen(f.X)
	}
	if fn, ok := expressionObject(p.info, fun).(*types.Func); ok {
		sig = signature(fn.Origin().Type())
	}
	if refs := l.resultTypes[sig]; index < len(refs) {
		ref := refs[index]
		if !hasTypeParameter(ref.pkg.info.TypeOf(ref.expr)) {
			return typeSyntaxString(ref.pkg, ref.expr)
		}
	}
	return ""
}

func bareNamed(t types.Type) *types.Named {
	if ptr, ok := t.(*types.Pointer); ok {
		t = ptr.Elem()
	}
	n, _ := t.(*types.Named)
	return n
}

func (c *checker) methodName(sel *ast.SelectorExpr, fn *types.Func) string {
	if !c.loader.aliasMode {
		return fn.FullName()
	}
	sig := signature(fn.Type())
	if sig == nil || sig.Recv() == nil {
		return fn.FullName()
	}
	recv, operand := bareNamed(sig.Recv().Type()), bareNamed(c.pkg.info.TypeOf(sel.X))
	if recv == nil || operand == nil || recv.Obj() != operand.Obj() {
		return fn.FullName()
	}
	s := c.loader.expressionTypeString(c.pkg, sel.X, make(map[types.Object]bool))
	s = strings.TrimPrefix(s, "*")
	name := qualifiedName(recv.Obj())
	if s != name && !strings.HasPrefix(s, name+"[") {
		return fn.FullName()
	}
	if _, ptr := sig.Recv().Type().(*types.Pointer); ptr {
		s = "*" + s
	}
	return "(" + s + ")." + fn.Name()
}
